#!/usr/bin/env bash

# Synopsis:
# Run the fixture suite inside the Docker image.
#
# This is the authoritative check: the expected files in tests/ are generated by
# bin/run-tests.sh against whatever `v` is on the host, which may not be the
# pinned version, and may not have jq. Running them here proves the image and
# the checked-in expectations agree.
#
# Example:
# ./bin/run-tests-in-docker.sh

set -uo pipefail

cd "$(dirname "$0")/.." || exit 1

# Git Bash on Windows rewrites any argument that looks like a POSIX path into a
# Windows path before docker sees it, which turns the container's /solution/ into
# "C:/Program Files/Git/solution/". So the automatic conversion is turned off
# and the host paths are converted explicitly instead. On Linux, MSYS_NO_PATHCONV
# is a harmless no-op and cygpath does not exist.
export MSYS_NO_PATHCONV=1
export MSYS2_ARG_CONV_EXCL='*'

to_docker_path() {
    if command -v cygpath >/dev/null 2>&1; then
        cygpath -m "$1"
    else
        printf '%s' "$1"
    fi
}

image="${IMAGE:-exercism/vlang-representer:dev}"

echo "building ${image}..."
docker build -t "$image" . || exit 1

exit_code=0
workdir="$(mktemp -d)"
trap 'rm -rf "$workdir"' EXIT

for test_dir in tests/*/; do
    [ -d "$test_dir" ] || continue
    name="$(basename "$test_dir")"
    source_path="$(cd "$test_dir" && pwd)"

    target="${workdir}/${name}"
    mkdir -p "$target"
    cp -r "${test_dir}/." "$target/"

    target_docker="$(to_docker_path "$target")"

    if [ -f "$target/.expect-error" ]; then
        if docker run --rm --network none \
            --mount "type=bind,src=${target_docker},dst=/solution,readonly" \
            --mount "type=bind,src=${target_docker},dst=/output" \
            "$image" "$name" /solution/ /output/ >/dev/null 2>&1; then
            echo "FAIL ${name}: expected a non-zero exit code"
            exit_code=1
        else
            echo "PASS ${name}: failed as expected"
        fi
        continue
    fi

    if ! docker run --rm --network none \
        --mount "type=bind,src=${target_docker},dst=/solution,readonly" \
        --mount "type=bind,src=${target_docker},dst=/output" \
        "$image" "$name" /solution/ /output/ >/dev/null 2>&1; then
        echo "FAIL ${name}: representer exited non-zero"
        exit_code=1
        continue
    fi

    for pair in \
        "representation.txt:expected_representation.txt" \
        "mapping.json:expected_mapping.json" \
        "representation.json:expected_representation.json"
    do
        actual="${target}/${pair%%:*}"
        expected="${target}/${pair##*:}"

        if diff -u "$expected" "$actual" >/dev/null 2>&1; then
            echo "PASS ${name}: ${pair%%:*}"
        else
            echo "FAIL ${name}: ${pair%%:*} differs inside the image"
            diff -u "$expected" "$actual" | head -40
            exit_code=1
        fi
    done

    equivalent_to_file="${target}/equivalent-to"
    if [ -f "$equivalent_to_file" ]; then
        other_name="$(tr -d '[:space:]' < "$equivalent_to_file")"
        if [ -f "${workdir}/${other_name}/representation.txt" ]; then
            if diff -q "${target}/representation.txt" "${workdir}/${other_name}/representation.txt" >/dev/null 2>&1; then
                echo "PASS ${name}: same representation as ${other_name}"
            else
                echo "FAIL ${name}: representation differs from ${other_name}"
                exit_code=1
            fi
        fi
    fi
done

exit "$exit_code"
